-- Default page: the home page (slug "home"). Only adds it if missing. From api/:
--   live:  npx wrangler d1 execute somefreq-db --remote --file default-pages/home.sql
--   local: npx wrangler d1 execute somefreq-db --local --file default-pages/home.sql
-- Stopgap until default pages get a migration system.
INSERT OR IGNORE INTO site_pages (slug, name, published, content_json, created_at, updated_at) VALUES ('home', 'Home', 1, '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "Michael Higginson"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "I''m Michael, a full-stack developer with over a decade of experience. I''m most at home in the TypeScript ecosystem, but I''m also comfortable in Python, Java and Rust."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "By day I''m a Systems Developer at Aluminati, building heavily bespoke community platforms for universities and large enterprises."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "My background is in design and marketing, and it still shapes how I build."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Outside work, I''m building the framework this site runs on, making a game in Bevy (a Rust game engine) set in an overworld I''ve been developing, and experimenting with how to work well with AI. Once the framework is ready, this is where that work, and my thoughts on it, will live."}]}]}', unixepoch(), unixepoch());
